/**
 * Multilingual strings — Hindi is default (docs/KisanQ_UIUX_Spec.md principle 6).
 * The very first Splash/language-select screen deliberately only offers Hindi/English (kept
 * simple for a farmer's first-ever open of the app — see SplashScreen.tsx); every other
 * supported language lives in Settings (SettingsScreen.tsx), reachable any time after.
 *
 * Language set is deliberately not all 22 Eighth-Schedule languages: it's the 9 with the
 * largest speaker populations and the most agricultural-state relevance (Bengali, Marathi,
 * Gujarati, Telugu, Tamil, Kannada, Malayalam, Odia, Urdu) plus Hindi/English/Punjabi, chosen
 * because translation quality matters more than raw coverage — a wrong or unnatural translation
 * in a government-facing app is worse than an honest gap. Assamese, Maithili, Sanskrit, Nepali,
 * Konkani, Dogri, Kashmiri, Bodo, Manipuri, and Santali are real, deliberate omissions, not
 * oversights — add them the same way if a native/fluent reviewer is available to check them.
 * Urdu is rendered left-to-right here like every other language (React Native's default text
 * direction) — true RTL layout is a separate, larger change not done in this pass.
 *
 * Exact copy from docs/KisanQ_UIUX_Spec.md and docs/KisanQ_Missing_Details_Polish.md is used
 * verbatim (Hindi/English) where the spec gives it, rather than inventing new wording
 * (CLAUDE.md rule 4); every other language's wording matches the same tone and register.
 */
/**
 * The supported languages, as the single source of truth: `Lang` is derived from this array
 * rather than written out separately, so a language can never exist in the type but be missing
 * from the runtime list (which is what a stored-language check, or any "list every language"
 * UI, needs to iterate).
 */
export const LANGS = [
  "hi", "en", "pa", "bn", "mr", "gu", "te", "ta", "kn", "ml", "or", "ur",
] as const;

export type Lang = (typeof LANGS)[number];

