export type StringKey = keyof typeof strings;

export function t(key: StringKey, lang: Lang): string {
  return strings[key][lang];
}

/**
 * Translate a string that *might* be one of our keys, falling back to the value itself.
 *
 * For values that were stored in Firestore rather than written in a screen: consent records
 * keep the requested data fields and the purpose as translation keys so they can be re-read in
 * whichever language the farmer is using later, but records written before that change hold
 * plain English text. Showing that English back is far better than showing a blank row or
 * crashing on a key that doesn't exist.
 */
export function tryT(value: string, lang: Lang): string {
  return value in strings ? strings[value as StringKey][lang] : value;
}
